//	              |=.| |.-----.|
//	              |--| ||     ||
//	              |  | |'-----'|
//	              |__|~')_____('
//	                [ COMPUTER ]
//
//	                  North (0,-1)
//	                      ^
//	                      |
//	                      |
//	(-1,0)  West <----[ HAPTIC ]----> East (1,0)
//	                      |
//	                      |
//	                      v
