var fnGetHapticID func(haptic *Haptic) HapticID

// Get the instance ID of an opened haptic device.
//
// Parameters:
//   - haptic: the Haptic device to query.
//
// Returns: the instance ID of the specified haptic device on success or 0 on failure; call GetError() for more information.
//
// Since: SDL 3.2.0.
func GetHapticID(haptic *Haptic) HapticID {
	return fnGetHapticID(haptic)
}

var fnGetHapticName func(haptic *Haptic) *byte

// Get the implementation dependent name of a haptic device.
//
// Parameters:
//   - haptic: the Haptic obtained from OpenJoystick().
//
// Returns: the name of the selected haptic device. If no name can be found, this function returns NULL; call GetError() for more information.
//
// Since: SDL 3.2.0.
//
// See also: GetHapticNameForID
func GetHapticName(haptic *Haptic) string {
	return GoString(fnGetHapticName(haptic))
}

var fnIsMouseHaptic func() bool

// Query whether or not the current mouse has haptic capabilities.
//
// Returns: true if the mouse is haptic or false if it isn't.
//
// Since: SDL 3.2.0.
//
// See also: OpenHapticFromMouse
func IsMouseHaptic() bool {
	return fnIsMouseHaptic()
}

var fnOpenHapticFromMouse func() *Haptic

// Try to open a haptic device from the current mouse.
//
// Returns: the haptic device identifier or NULL on failure; call GetError() for more information.
//
// Since: SDL 3.2.0.
//
// See also: CloseHaptic, IsMouseHaptic
func OpenHapticFromMouse() *Haptic {
	return fnOpenHapticFromMouse()
}

var fnIsJoystickHaptic func(joystick *Joystick) bool

// Query if a joystick has haptic features.
//
// Parameters:
//   - joystick: the Joystick to test for haptic capabilities.
//
// Returns: true if the joystick is haptic or false if it isn't.
//
// Since: SDL 3.2.0.
//
// See also: OpenHapticFromJoystick
func IsJoystickHaptic(joystick *Joystick) bool {
	return fnIsJoystickHaptic(joystick)
}

var fnOpenHapticFromJoystick func(joystick *Joystick) *Haptic

// Open a haptic device for use from a joystick device.
//
// You must still close the haptic device separately. It will not be closed
// with the joystick.
//
// When opened from a joystick you should first close the haptic device before
// closing the joystick device. If not, on some implementations the haptic
// device will also get unallocated and you'll be unable to use force feedback
// on that device.
//
// Parameters:
//   - joystick: the Joystick to create a haptic device from.
//
// Returns: a valid haptic device identifier on success or NULL on failure; call GetError() for more information.
//
// Since: SDL 3.2.0.
//
// See also: CloseHaptic, IsJoystickHaptic
func OpenHapticFromJoystick(joystick *Joystick) *Haptic {
	return fnOpenHapticFromJoystick(joystick)
}

var fnCloseHaptic func(haptic *Haptic)

// Close a haptic device previously opened with OpenHaptic().
//
// Parameters:
//   - haptic: the Haptic device to close.
//
// Since: SDL 3.2.0.
//
// See also: OpenHaptic
func CloseHaptic(haptic *Haptic) {
	fnCloseHaptic(haptic)
}

var fnGetMaxHapticEffects func(haptic *Haptic) int32

// Get the number of effects a haptic device can store.
//
// On some platforms this isn't fully supported, and therefore is an
// approximation. Always check to see if your created effect was actually
// created and do not rely solely on GetMaxHapticEffects().
//
// Parameters:
//   - haptic: the Haptic device to query.
//
// Returns: the number of effects the haptic device can store or a negative error code on failure; call GetError() for more information.
//
// Since: SDL 3.2.0.
//
// See also: GetMaxHapticEffectsPlaying, GetHapticFeatures
func GetMaxHapticEffects(haptic *Haptic) int32 {
	return fnGetMaxHapticEffects(haptic)
}

var fnGetMaxHapticEffectsPlaying func(haptic *Haptic) int32

// Get the number of effects a haptic device can play at the same time.
//
// This is not supported on all platforms, but will always return a value.
//
// Parameters:
//   - haptic: the Haptic device to query maximum playing effects.
//
// Returns: the number of effects the haptic device can play at the same time or -1 on failure; call GetError() for more information.
//
// Since: SDL 3.2.0.
//
// See also: GetMaxHapticEffects, GetHapticFeatures
func GetMaxHapticEffectsPlaying(haptic *Haptic) int32 {
	return fnGetMaxHapticEffectsPlaying(haptic)
}

var fnGetHapticFeatures func(haptic *Haptic) uint32

// Get the haptic device's supported features in bitwise manner.
//
// Parameters:
//   - haptic: the Haptic device to query.
//
// Returns: a list of supported haptic features in bitwise manner (OR'd), or 0 on failure; call GetError() for more information.
//
// Since: SDL 3.2.0.
//
// See also: HapticEffectSupported, GetMaxHapticEffects
func GetHapticFeatures(haptic *Haptic) uint32 {
	return fnGetHapticFeatures(haptic)
}

var fnGetNumHapticAxes func(haptic *Haptic) int32

// Get the number of haptic axes the device has.
//
// The number of haptic axes might be useful if working with the
// HapticDirection effect.
//
// Parameters:
//   - haptic: the Haptic device to query.
//
// Returns: the number of axes on success or -1 on failure; call GetError() for more information.
//
// Since: SDL 3.2.0.
func GetNumHapticAxes(haptic *Haptic) int32 {
	return fnGetNumHapticAxes(haptic)
}

var fnHapticEffectSupported func(haptic *Haptic, effect *HapticEffect) bool

// Check to see if an effect is supported by a haptic device.
//
// Parameters:
//   - haptic: the Haptic device to query.
//   - effect: the desired effect to query.
//
// Returns: true if the effect is supported or false if it isn't.
//
// Since: SDL 3.2.0.
//
// See also: CreateHapticEffect, GetHapticFeatures
func HapticEffectSupported(haptic *Haptic, effect *HapticEffect) bool {
	return fnHapticEffectSupported(haptic, effect)
}

var fnCreateHapticEffect func(haptic *Haptic, effect *HapticEffect) HapticEffectID

// Create a new haptic effect on a specified device.
//
// Parameters:
//   - haptic: an Haptic device to create the effect on.
//   - effect: an HapticEffect structure containing the properties of the effect to create.
//
// Returns: the ID of the effect on success or -1 on failure; call GetError() for more information.
//
// Since: SDL 3.2.0.
//
// See also: DestroyHapticEffect, RunHapticEffect, UpdateHapticEffect
func CreateHapticEffect(haptic *Haptic, effect *HapticEffect) HapticEffectID {
	return fnCreateHapticEffect(haptic, effect)
}

var fnUpdateHapticEffect func(haptic *Haptic, effect HapticEffectID, data *HapticEffect) bool

// Update the properties of an effect.
//
// Can be used dynamically, although behavior when dynamically changing
// direction may be strange. Specifically the effect may re-upload itself and
// start playing from the start. You also cannot change the type either when
// running UpdateHapticEffect().
//
// Parameters:
//   - haptic: the Haptic device that has the effect.
//   - effect: the identifier of the effect to update.
//   - data: an HapticEffect structure containing the new effect properties to use.
//
// Returns: true on success or false on failure; call GetError() for more information.
//
// Since: SDL 3.2.0.
//
// See also: CreateHapticEffect, RunHapticEffect
func UpdateHapticEffect(haptic *Haptic, effect HapticEffectID, data *HapticEffect) bool {
	return fnUpdateHapticEffect(haptic, effect, data)
}

var fnRunHapticEffect func(haptic *Haptic, effect HapticEffectID, iterations uint32) bool

// Run the haptic effect on its associated haptic device.
//
// To repeat the effect over and over indefinitely, set `iterations` to
// `HAPTIC_INFINITY`. (Repeats the envelope - attack and fade.) To make
// one instance of the effect last indefinitely (so the effect does not fade),
// set the effect's `length` in its structure/union to `HAPTIC_INFINITY`
// instead.
//
// Parameters:
//   - haptic: the Haptic device to run the effect on.
//   - effect: the ID of the haptic effect to run.
//   - iterations: the number of iterations to run the effect; use `HAPTIC_INFINITY` to repeat forever.
//
// Returns: true on success or false on failure; call GetError() for more information.
//
// Since: SDL 3.2.0.
//
// See also: GetHapticEffectStatus, StopHapticEffect, StopHapticEffects
func RunHapticEffect(haptic *Haptic, effect HapticEffectID, iterations uint32) bool {
	return fnRunHapticEffect(haptic, effect, iterations)
}

var fnStopHapticEffect func(haptic *Haptic, effect HapticEffectID) bool

// Stop the haptic effect on its associated haptic device.
//
// Parameters:
//   - haptic: the Haptic device to stop the effect on.
//   - effect: the ID of the haptic effect to stop.
//
// Returns: true on success or false on failure; call GetError() for more information.
//
// Since: SDL 3.2.0.
//
// See also: RunHapticEffect, StopHapticEffects
func StopHapticEffect(haptic *Haptic, effect HapticEffectID) bool {
	return fnStopHapticEffect(haptic, effect)
}

var fnDestroyHapticEffect func(haptic *Haptic, effect HapticEffectID)

// Destroy a haptic effect on the device.
//
// This will stop the effect if it's running. Effects are automatically
// destroyed when the device is closed.
//
// Parameters:
//   - haptic: the Haptic device to destroy the effect on.
//   - effect: the ID of the haptic effect to destroy.
//
// Since: SDL 3.2.0.
//
// See also: CreateHapticEffect
func DestroyHapticEffect(haptic *Haptic, effect HapticEffectID) {
	fnDestroyHapticEffect(haptic, effect)
}

var fnGetHapticEffectStatus func(haptic *Haptic, effect HapticEffectID) bool

// Get the status of the current effect on the specified haptic device.
//
// Device must support the HAPTIC_STATUS feature.
//
// Parameters:
//   - haptic: the Haptic device to query for the effect status on.
//   - effect: the ID of the haptic effect to query its status.
//
// Returns: true if it is playing, false if it isn't playing or haptic status isn't supported.
//
// Since: SDL 3.2.0.
//
// See also: GetHapticFeatures
func GetHapticEffectStatus(haptic *Haptic, effect HapticEffectID) bool {
	return fnGetHapticEffectStatus(haptic, effect)
}

var fnSetHapticGain func(haptic *Haptic, gain int32) bool

// Set the global gain of the specified haptic device.
//
// Device must support the HAPTIC_GAIN feature.
//
// The user may specify the maximum gain by setting the environment variable
// `SDL_HAPTIC_GAIN_MAX` which should be between 0 and 100. All calls to
// SetHapticGain() will scale linearly using `SDL_HAPTIC_GAIN_MAX` as the
// maximum.
//
// Parameters:
//   - haptic: the Haptic device to set the gain on.
//   - gain: value to set the gain to, should be between 0 and 100 (0 - 100).
//
// Returns: true on success or false on failure; call GetError() for more information.
//
// Since: SDL 3.2.0.
//
// See also: GetHapticFeatures
func SetHapticGain(haptic *Haptic, gain int32) bool {
	return fnSetHapticGain(haptic, gain)
}

var fnSetHapticAutocenter func(haptic *Haptic, autocenter int32) bool

// Set the global autocenter of the device.
//
// Autocenter should be between 0 and 100. Setting it to 0 will disable
// autocentering.
//
// Device must support the HAPTIC_AUTOCENTER feature.
//
// Parameters:
//   - haptic: the Haptic device to set autocentering on.
//   - autocenter: value to set autocenter to (0-100).
//
// Returns: true on success or false on failure; call GetError() for more information.
//
// Since: SDL 3.2.0.
//
// See also: GetHapticFeatures
func SetHapticAutocenter(haptic *Haptic, autocenter int32) bool {
	return fnSetHapticAutocenter(haptic, autocenter)
}

var fnPauseHaptic func(haptic *Haptic) bool

// Pause a haptic device.
//
// Device must support the `HAPTIC_PAUSE` feature. Call ResumeHaptic()
// to resume playback.
